// ================== EDIT THESE VALUES ==================
const SETTINGS = {
  testMode: true,                 // true = back up only `testLimit` workflows into the test/ folder
  testLimit: 2,
  githubOwner: 'YOUR_GITHUB_USERNAME',
  githubRepo: 'n8n-backups',
  githubBranch: 'main',
  n8nBaseUrl: 'https://n8n.snova.com',
  telegramChatId: 'YOUR_TELEGRAM_CHAT_ID',
  personalProjectId: '',          // optional, see SETUP.md: only back up workflows owned by this project
  secretScanIgnoreWorkflowIds: [], // workflow IDs to skip in the secret scan (confirmed false positives only)
  maxDropPercent: 50,             // safety stop if the workflow count falls by more than this vs latest/
};
// ============== NOTHING TO EDIT BELOW THIS LINE ==============
const placeholders = ['YOUR_GITHUB_USERNAME', 'YOUR_TELEGRAM_CHAT_ID'];
for (const [k, v] of Object.entries(SETTINGS)) {
  if (placeholders.includes(v)) throw new Error(`Config: please set "${k}" in the Config node.`);
}
const timezone = 'Asia/Kathmandu';
const now = $now.setZone(timezone);

let triggerType = 'manual';
try {
  if ($('Every night at 02:00').isExecuted) triggerType = 'scheduled';
} catch (e) {}

const base = SETTINGS.n8nBaseUrl.replace(/\/+$/, '');
const root = SETTINGS.testMode ? 'test/' : '';
const date = now.toFormat('yyyy-MM-dd');

return [{
  json: {
    ...SETTINGS,
    n8nBaseUrl: base,
    timezone,
    triggerType,
    date,
    time: now.toFormat('HH:mm'),
    startedAtMs: Date.now(),
    snapshotDir: `${root}backups/${date}`,
    latestDir: `${root}latest`,
    executionUrl: `${base}/workflow/${$workflow.id}/executions/${$execution.id}`,
  },
}];

// Turns the workflows returned by the n8n API into clean, secret-free files.
const cfg = $('Config').first().json;

let wfs = $input.all().map(i => i.json).filter(w => w && typeof w.id === 'string' && Array.isArray(w.nodes));
const visibleCount = wfs.length;

if (cfg.personalProjectId) {
  wfs = wfs.filter(w => (w.shared || []).some(s => s.projectId === cfg.personalProjectId && s.role === 'workflow:owner'));
}
wfs.sort((a, b) => String(a.name).localeCompare(String(b.name)) || a.id.localeCompare(b.id));
if (cfg.testMode) wfs = wfs.slice(0, cfg.testLimit);

if (wfs.length === 0) {
  throw new Error(`No workflows to back up (the n8n API returned ${visibleCount}). Stopped so that latest/ is not emptied. Check the n8n API credential and personalProjectId in Config.`);
}

// ---- readable, safe file names ----
function safeName(name) {
  let s = String(name || '')
    .normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^A-Za-z0-9._-]+/g, '-')
    .replace(/-{2,}/g, '-')
    .replace(/^[-._]+|[-._]+$/g, '');
  s = s.slice(0, 80).replace(/[-._]+$/g, '');
  return s || 'untitled';
}

// ---- secret scan (values are never printed, only where they are) ----
const PATTERNS = [
  ['GitHub token', /\b(gh[pousr]_[A-Za-z0-9]{36,}|github_pat_[A-Za-z0-9_]{22,})/],
  ['OpenAI/Anthropic-style key', /\bsk-(?:proj-|ant-)?[A-Za-z0-9_-]{20,}/],
  ['Stripe live key', /\b[sr]k_live_[A-Za-z0-9]{20,}/],
  ['AWS access key', /\bAKIA[0-9A-Z]{16}\b/],
  ['Google API key', /\bAIza[0-9A-Za-z_-]{35}/],
  ['Slack token', /\bxox[abposr]-[A-Za-z0-9-]{10,}/],
  ['Telegram bot token', /\b\d{8,10}:AA[A-Za-z0-9_-]{33}\b/],
  ['Private key', new RegExp('-----BEGIN ' + '[A-Z ]*PRIVATE KEY-----')],
  ['Hard-coded Bearer token', /Bearer\s+[A-Za-z0-9._~+\/-]{24,}=*/],
  ['JWT', /\beyJ[A-Za-z0-9_-]{10,}\.eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}/],
];
const ignore = new Set(cfg.secretScanIgnoreWorkflowIds || []);
const findings = [];
function scan(wfName, where, value) {
  const text = typeof value === 'string' ? value : JSON.stringify(value ?? '');
  for (const [label, re] of PATTERNS) if (re.test(text)) findings.push(`"${wfName}" › ${where} (${label})`);
}

const files = [];
const manifestRows = [];

for (const w of wfs) {
  const fileName = `${safeName(w.name)}__${safeName(w.id)}.json`;

  // Keep what is needed to restore; drop pinned data, static data and sharing info.
  const clean = {
    id: w.id,
    name: w.name,
    active: w.active,
    isArchived: w.isArchived,
    versionId: w.versionId,
    activeVersionId: w.activeVersionId ?? null,
    createdAt: w.createdAt,
    updatedAt: w.updatedAt,
    tags: (w.tags || []).map(t => ({ id: t.id, name: t.name })),
    nodes: w.nodes,
    connections: w.connections,
    ...(Array.isArray(w.nodeGroups) && w.nodeGroups.length ? { nodeGroups: w.nodeGroups } : {}),
    settings: w.settings || {},
    meta: w.meta || null,
    pinData: {},
  };

  if (!ignore.has(w.id)) {
    for (const n of clean.nodes) scan(w.name, `node "${n.name}"`, { p: n.parameters, notes: n.notes });
    scan(w.name, 'workflow settings/meta', { s: clean.settings, m: clean.meta });
  }

  files.push({ kind: 'workflow', fileName, content: JSON.stringify(clean, null, 2) + '\n' });
  manifestRows.push({
    id: w.id,
    name: w.name,
    file: fileName,
    active: !!w.active,
    published: !!w.active,
    activeVersionId: w.activeVersionId ?? null,
    isArchived: !!w.isArchived,
    createdAt: w.createdAt,
    updatedAt: w.updatedAt,
    folder: null,
    tags: (w.tags || []).map(t => t.name),
    nodeCount: w.nodes.length,
  });
}

if (findings.length) {
  const shown = findings.slice(0, 8).join('; ');
  const more = findings.length > 8 ? ` …and ${findings.length - 8} more` : '';
  throw new Error(`Secret scan stopped the backup. Possible secrets typed directly into: ${shown}${more}. Move them into n8n credentials and run again. Nothing was uploaded.`);
}

const manifest = {
  backupDate: cfg.date,
  backupTime: cfg.time,
  timezone: cfg.timezone,
  trigger: cfg.triggerType,
  testMode: cfg.testMode,
  source: cfg.n8nBaseUrl,
  workflowCount: manifestRows.length,
  archivedCount: manifestRows.filter(r => r.isArchived).length,
  notes: [
    'folder is always null: the n8n public API does not return the folder of a workflow.',
    'Pinned data and static data are removed. Credentials are references (id + name) only, never secrets.',
  ],
  workflows: manifestRows,
};
files.push({ kind: 'manifest', fileName: '_manifest.json', content: JSON.stringify(manifest, null, 2) + '\n' });

return files.map(f => ({ json: f }));

// Checks the uploads and builds ONE tree that only touches today's folder and latest/.
const cfg = $('Config').first().json;
const files = $('Prepare files').all().map(i => i.json);
const blobs = $input.all().map(i => i.json);

function errText(j) {
  const e = j && j.error;
  if (!e) return 'no SHA returned';
  if (typeof e === 'string') return e;
  return [e.message, e.description].filter(Boolean).join(' – ') || JSON.stringify(e).slice(0, 300);
}

if (blobs.length !== files.length) {
  throw new Error(`Upload check failed: expected ${files.length} uploaded files, got ${blobs.length}.`);
}
const bad = [];
blobs.forEach((b, i) => {
  if (!b || typeof b.sha !== 'string' || !/^[0-9a-f]{40}$/.test(b.sha)) bad.push(`${files[i].fileName}: ${errText(b)}`);
});
if (bad.length) throw new Error(`Uploading ${bad.length} file(s) to GitHub failed. First error – ${bad[0]}`);

const branch = $('Get branch').first().json;
const parentSha = branch.commit.sha;
const baseTree = branch.commit.commit.tree.sha;

const existing = $('Get existing files').first().json;
if (existing.truncated) {
  throw new Error('GitHub returned an incomplete file list because the repo is very large. Delete old snapshots (see SETUP.md → Cleaning old snapshots) and run again.');
}

const snap = cfg.snapshotDir + '/';
const latest = cfg.latestDir + '/';
const inScope = p => p.startsWith(snap) || p.startsWith(latest);

const entries = [];
const wanted = new Set();
files.forEach((f, i) => {
  for (const dir of [snap, latest]) {
    const path = dir + f.fileName;
    wanted.add(path);
    entries.push({ path, mode: '100644', type: 'blob', sha: blobs[i].sha });
  }
});

const existingPaths = (existing.tree || []).filter(e => e.type === 'blob').map(e => e.path);
const toDelete = existingPaths.filter(p => inScope(p) && !wanted.has(p));
for (const path of toDelete) entries.push({ path, mode: '100644', type: 'blob', sha: null });

// Safety: never touch anything outside today's folder and latest/.
for (const e of entries) {
  if (!inScope(e.path)) throw new Error(`Safety stop: the workflow tried to change "${e.path}", which is outside ${snap} and ${latest}.`);
}

const workflowCount = files.filter(f => f.kind === 'workflow').length;
const latestCount = existingPaths.filter(p => p.startsWith(latest) && p.endsWith('.json') && !p.endsWith('/_manifest.json')).length;
const minAllowed = Math.ceil(latestCount * (1 - cfg.maxDropPercent / 100));
if (!cfg.testMode && latestCount >= 4 && workflowCount < minAllowed) {
  throw new Error(`Safety stop: only ${workflowCount} workflows found, but latest/ has ${latestCount}. That is a drop of more than ${cfg.maxDropPercent}%. If this is expected, raise maxDropPercent in Config and run again.`);
}

const archivedCount = JSON.parse(files.find(f => f.kind === 'manifest').content).archivedCount;
const message = `${cfg.testMode ? '[TEST] ' : ''}Backup ${cfg.date} ${cfg.time} (${cfg.triggerType}) – ${workflowCount} workflows`;

return [{
  json: {
    base_tree: baseTree,
    tree: entries,
    parentSha,
    message,
    workflowCount,
    archivedCount,
    removedCount: toDelete.length,
  },
}];

const cfg = $('Config').first().json;
const info = $('Build new tree').first().json;
const commit = $('Create commit').first().json;

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const secs = Math.max(0, Math.round((Date.now() - cfg.startedAtMs) / 1000));
const duration = secs >= 60 ? `${Math.floor(secs / 60)}m ${secs % 60}s` : `${secs}s`;
const commitUrl = commit.html_url || `https://github.com/${cfg.githubOwner}/${cfg.githubRepo}/commit/${commit.sha}`;

const lines = [
  `✅ <b>n8n backup succeeded</b>${cfg.testMode ? ' 🧪 <b>TEST MODE</b>' : ''}`,
  `🗓 ${esc(cfg.date)} ${esc(cfg.time)} (${esc(cfg.timezone)})`,
  `⚙️ Trigger: ${esc(cfg.triggerType)}`,
  `📦 Workflows: ${info.workflowCount}${info.archivedCount ? ` (${info.archivedCount} archived)` : ''}`,
  `📁 Folder: ${esc(cfg.snapshotDir)}/`,
  ...(info.removedCount ? [`🧹 Removed from today/latest: ${info.removedCount} old file(s)`] : []),
  `🔗 Commit: <a href="${esc(commitUrl)}">${esc(String(commit.sha).slice(0, 7))}</a>`,
  `⏱ Duration: ${duration}`,
];
return [{ json: { chatId: cfg.telegramChatId, text: lines.join('\n') } }];

// Runs when any step sends its error to the red "error" output.
let cfg = {};
try { cfg = $('Config').first().json; } catch (e) {}

let step = 'unknown step';
try { step = $prevNode.name; } catch (e) {}

const j = ($input.first() && $input.first().json) || {};
let msg;
const e = j.error;
if (!e) msg = JSON.stringify(j).slice(0, 500);
else if (typeof e === 'string') msg = e;
else msg = [e.message, e.description].filter(Boolean).join(' – ') || JSON.stringify(e).slice(0, 500);
if (msg.length > 1500) msg = msg.slice(0, 1500) + '…';

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const url = cfg.executionUrl || '';
const lines = [
  `❌ <b>n8n backup FAILED</b>${cfg.testMode ? ' 🧪 <b>TEST MODE</b>' : ''}`,
  `🗓 ${esc(cfg.date)} ${esc(cfg.time)} (${esc(cfg.timezone)})`,
  `⚙️ Trigger: ${esc(cfg.triggerType)}`,
  `🧩 Failed step: <b>${esc(step)}</b>`,
  `💬 Error: ${esc(msg)}`,
  ...(url ? [`🔎 Execution: <a href="${esc(url)}">open in n8n</a>`] : []),
  `ℹ️ The GitHub branch was not changed.`,
];
return [{
  json: {
    chatId: cfg.telegramChatId,
    text: lines.join('\n'),
    plain: `Backup failed at "${step}": ${msg}`,
  },
}];
